1	package hotel.web;
2	
3	import static org.junit.jupiter.api.Assertions.assertEquals;
4	import static org.junit.jupiter.api.Assertions.assertTrue;
5	
6	import com.fasterxml.jackson.databind.JsonNode;
7	import com.fasterxml.jackson.databind.ObjectMapper;
8	import hotel.Hotel;
9	import java.io.IOException;
10	import java.net.URI;
11	import java.net.http.HttpClient;
12	import java.net.http.HttpRequest;
13	import java.net.http.HttpResponse;
14	import org.junit.jupiter.api.AfterEach;
15	import org.junit.jupiter.api.BeforeEach;
16	import org.junit.jupiter.api.Test;
17	
18	class HttpApiTest {
19	
20	    private static final String RESERVATION_JSON = """
21	            {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
22	             "guestCpf": "111.222.333-44", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
23	             "guests": 2, "ratePlan": "STANDARD"}
24	            """;
25	
26	    private final HttpClient client = HttpClient.newHttpClient();
27	    private final ObjectMapper json = new ObjectMapper();
28	    private Hotel hotel;
29	    private String baseUrl;
30	
31	    @BeforeEach
32	    void startHotel() {
33	        hotel = new Hotel();
34	        baseUrl = "http://localhost:" + hotel.start(0);
35	    }
36	
37	    @AfterEach
38	    void stopHotel() {
39	        hotel.stop();
40	    }
41	
42	    private HttpResponse<String> get(String path) throws IOException, InterruptedException {
43	        return client.send(HttpRequest.newBuilder(URI.create(baseUrl + path)).GET().build(),
44	                HttpResponse.BodyHandlers.ofString());
45	    }
46	
47	    private HttpResponse<String> post(String path, String body) throws IOException, InterruptedException {
48	        return client.send(HttpRequest.newBuilder(URI.create(baseUrl + path))
49	                        .header("Content-Type", "application/json")
50	                        .POST(HttpRequest.BodyPublishers.ofString(body))
51	                        .build(),
52	                HttpResponse.BodyHandlers.ofString());
53	    }
54	
55	    @Test
56	    void listsTheRooms() throws Exception {
57	        HttpResponse<String> response = get("/rooms");
58	
59	        assertEquals(200, response.statusCode());
60	        JsonNode rooms = json.readTree(response.body());
61	        assertEquals(5, rooms.size());
62	        assertEquals(101, rooms.get(0).get("number").asInt());
63	        assertEquals("249.9", rooms.get(0).get("nightlyRate").asText());
64	    }
65	
66	    @Test
67	    void booksConfirmsAndChecksOut() throws Exception {
68	        HttpResponse<String> created = post("/reservations", RESERVATION_JSON);
69	        assertEquals(201, created.statusCode());
70	        JsonNode reservation = json.readTree(created.body());
71	        long id = reservation.get("id").asLong();
72	        assertEquals("PENDING", reservation.get("status").asText());
73	        assertEquals("2027-07-10", reservation.get("checkIn").asText());
74	        assertEquals(935.76, reservation.get("total").asDouble());
75	
76	        assertEquals(200, post("/reservations/" + id + "/confirmation", "").statusCode());
77	        JsonNode messages = json.readTree(get("/messages").body());
78	        assertEquals(1, messages.size());
